//! Loads the object configuration generated by a real Checkmk Community 2.5 site.

use std::path::PathBuf;

fn fixture_files() -> Vec<PathBuf> {
    let dir = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/checkmk");
    ["templates.cfg", "check_mk_templates.cfg", "check_mk_objects.cfg"].iter().map(|f| dir.join(f)).collect()
}

#[test]
fn checkmk_generated_config_resolves() {
    let (cfg, warnings) = corax_config::load_objects(&fixture_files()).expect("fixture must load");
    assert!(warnings.is_empty(), "unexpected warnings: {warnings:?}");
    assert_eq!(cfg.hosts.len(), 3);

    let db01 = cfg.hosts.iter().find(|h| h.name == "db01").unwrap();
    assert_eq!(db01.address, "127.0.0.1");
    assert_eq!(db01.common.max_check_attempts, 1);
    assert_eq!(db01.common.check_command.as_ref().unwrap().name, "check-mk-host-ping");
    assert!(db01.hostgroups.contains(&"check_mk".to_string()));
    // hex-encoded labels survive as custom variables
    assert!(db01.common.custom_vars.iter().any(|(k, _)| k.starts_with("_LABEL_")));
    assert!(db01.common.action_url.contains("pnp4nagios"));

    let check_mk =
        cfg.services.iter().find(|s| s.host_name == "db01" && s.description == "Check_MK").expect("Check_MK service");
    assert!(check_mk.common.active_checks_enabled);
    assert_eq!(check_mk.common.check_command.as_ref().unwrap().name, "check-mk");

    let mem = cfg.services.iter().find(|s| s.host_name == "db01" && s.description == "Memory").unwrap();
    assert!(!mem.common.active_checks_enabled);
    assert!(mem.common.passive_checks_enabled);
    assert!(mem.common.process_perf_data);

    let notify = &cfg.commands["check-mk-notify"];
    assert!(notify.line.contains("NOTIFY_CONTACTNAME='$CONTACTNAME$'"));
    assert!(notify.line.trim_end().ends_with("check_mk --notify"));
}
